// Extract and minimally test the _astToText function
function _astToText(node, depth) {
  if (!node) return '''';
  const indent = ''  ''.repeat(depth);
  let line = indent + node.name;
  if (node.label) line += '' ['' + node.label + '']'';
  if (node.extra) line += '' ('' + node.extra + '')'';
  let text = line + ''\n'';
  if (node.children) {
    for (const c of node.children) text += _astToText(c, depth + 1);
  }
  return text;
}

